            current_sum = prefix[j] - (prefix[i-1] if i > 0 else 0)
            max_sum = max(max_sum, current_sum)

    # Case 2: One inversion
    for i in range(n):
        for j in range(i, n):
            current_sum = prefix[j] - (prefix[i-1] if i > 0 else 0)
            if a[i] < 0:
                current_sum += abs(a[i])
            elif a[j] < 0:
                current_sum += abs(a[j])
            max_sum = max(max_sum, current_sum)

    # Case 3: Two inversions
