def MaxSubarrayLength(arr, n, k):
    prefix_sum = 0
    prefix_map = {0: -1}
    max_len = -1

    for i in range(n):
        prefix_sum += arr[i]
        remainder = prefix_sum % k
        if remainder < 0:
            remainder += k

        if remainder in prefix_map:
            current_len = i - prefix_map[remainder]
            if current_len > max_len:
                max_len = current_len
        else:
            prefix_map[remainder] = i

    return max_len
