def countQuadruples(N):
    if N <= 0:
        return 0

    # Create a frequency array to store the count of each sum of squares
    max_sum = 2 * N * N + 1
    sum_counts = [0] * max_sum

    # Calculate all possible sums of squares for pairs (a, b)
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            sum_sq = a * a + b * b
            sum_counts[sum_sq] += 1

    # Count quadruples by iterating through all possible sums
    count = 0
    for s in sum_counts:
        if s > 0:
            # If there are k pairs that sum to s, then there are k^2 quadruples
            count += s * s

    return count
