def count_distinct_substrings(s: str, t: str) -> int:
    # Use a set to store all distinct substrings of s
    distinct_substrings = set()

    # Generate all substrings of s
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substring = s[i:j]
            distinct_substrings.add(substring)

    # Count how many distinct substrings of s are equal to t
