class RedBlackTree:
    RED = True
    BLACK = False

    def __init__(self):
        self.root = None

    def _is_red(self, node):
        return node is not None and node.color == self.RED

    def _rotate_left(self, node):
        right = node.right
        node.right = right.left
        if right.left:
            right.left.parent = node
        right.parent = node.parent
        if node.parent is None:
            self.root = right
        elif node == node.parent.left:
            node.parent.left = right
        else:
            node.parent.right = right
        right.left = node
        node.parent = right
        return right

    def _rotate_right(self, node):
        left = node.left
        node.left = left.right
        if left.right:
            left.right.parent = node
        left.parent = node.parent
        if node.parent is None:
            self.root = left
        elif node == node.parent.right:
            node.parent.right = left
        else:
            node.parent.left = left
        left.right = node
        node.parent = left
        return left

    def _insert_fixup(self, node):
        while self._is_red(node.parent) and node.parent != self.root:
            if node.parent == node.parent.parent.left:
                uncle = node.parent.parent.right
                if self._is_red(uncle):
                    node.parent.color = self.BLACK
                    uncle.color = self.BLACK
                    node.parent.parent.color = self.RED
                    node = node.parent.parent
                else:
                    if node == node.parent.right:
                        node = node.parent
                        self._rotate_left(node)
                    node.parent.color = self.BLACK
                    node.parent.parent.color = self.RED
                    self._rotate_right(node.parent.parent)
            else:
                uncle = node.parent.parent.left
                if self._is_red(uncle):
                    node.parent.color = self.BLACK
                    uncle.color = self.BLACK
                    node.parent.parent.color = self.RED
                    node = node.parent.parent
                else:
                    if node == node.parent.left:
                        node = node.parent
                        self._rotate_right(node)
                    node.parent.color = self.BLACK
                    node.parent.parent.color = self.RED
                    self._rotate_right(node.parent.parent)
        if self._is_red(self.root):
            self.root.color = self.BLACK
        return self.root

    def _insert(self, node, val):
        if node is None:
            return Node(val, self.RED, None, None, None)
        if val < node.value:
            node.left = self._insert(node.left, val)
            node.left.parent = node
        else:
            node.right = self._insert(node.right, val)
            node.right.parent = node
        return node

    def insert(self, val):
        if self.root is None:
            self.root = Node(val, self.BLACK, None, None, None)
        else:
            self.root = self._insert(self.root, val)
            self.root = self._insert_fixup(self.root)

    def search(self, val):
        node = self.root
        while node:
            if val == node.value:
                return True
            elif val < node.value:
                node = node.left
            else:
                node = node.right
        return False

