        if year % 400 == 0:
            return True
        if year % 100 == 0:
            return False
        if year % 4 == 0:
            return True
        return False

    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    weekday_counts = [0] * 7  # 0=Monday, 1=Tuesday, ..., 6=Sunday
    current_day = 0  # 0=Monday (Jan 1, 1900)

    for year in range(1900, 1900 + n):
        for month in range(12):
            if month == 1:
                days_in_month[1] = 29 if is_leap(year) else 28
            else:
                days_in_month[1] = 28 if is_leap(year) else 28

            # Calculate the day of the week for the 13th of the current month
            # The 13th is 12 days after the 1st
            weekday_counts[current_day] += 1
            current_day = (current_day + 12) % 7

            # Update current_day for the next month
            current_day = (current_day + days_in_month[month]) % 7

    return weekday_counts
