def multiply_sparse_matrices(matrix1, matrix2):
    # Initialize result matrix as a dictionary
    result = {}

    # Iterate over all elements in matrix1
    for row, col, value in matrix1.items():
        # Iterate over all elements in matrix2
        for row2, col2, value2 in matrix2.items():
            # Calculate the new row and column indices
            new_row = row + row2
            new_col = col + col2

            # Check if the new row and column indices are within the bounds of the result matrix
