def multiply_sparse_matrices(matrix1, matrix2):
    if not matrix1 or not matrix2:
        return {}

    # Get dimensions
    rows1 = set(r for r, c in matrix1.keys())
    cols1 = set(c for r, c in matrix1.keys())
    rows2 = set(r for r, c in matrix2.keys())
    cols2 = set(c for r, c in matrix2.keys())

    # Check if multiplication is possible
    if cols1 != rows2:
        raise ValueError("Matrix dimensions do not allow multiplication")

    # Get number of rows and columns for result
    num_rows = max(rows1) + 1 if rows1 else 0
    num_cols = max(cols2) + 1 if cols2 else 0

    # Initialize result dictionary
    result = {}

    # For each non-zero element in matrix1
    for (r1, c1), val1 in matrix1.items():
        # For each non-zero element in matrix2
        for (r2, c2), val2 in matrix2.items():
            # Check if column of matrix1 matches row of matrix2
            if c1 == r2:
                # Calculate result position and value
                result_pos = (r1, c2)
                result_val = val1 * val2

                # Add to result if not already present or if value is different
                if result_pos in result:
                    result[result_pos] += result_val
                else:
                    result[result_pos] = result_val

    # Remove zero values from result
    result = {k: v for k, v in result.items() if v != 0}

    return result
