    def decrypt(self, word2: str) -> int:
        if not word2:
            return 0

        count = 0
        stack = [(word2, 0)]

        while stack:
            current, idx = stack.pop()
            if idx == len(current):
                if current in self.dictionary_set:
                    count += 1
                continue

            # Try to split the remaining part into pairs
            remaining = current[idx:]
            for i in range(1, len(remaining) + 1, 2):
                if i % 2 == 1:
                    continue
                pair = remaining[:i]
                if pair in self.value_to_keys:
                    for key in self.value_to_keys[pair]:
                        stack.append((key + current[:idx], idx + i))

        return count
