from typing import List

class Encrypter:
    def __init__(self, keys: List[str], values: List[str], dictionary: List[str]):
        self.keys = keys
        self.values = values
        self.dictionary = dictionary
        self.key_map = {c: i for i, c in enumerate(keys)}
        self.value_to_keys = {}
        for i, v in enumerate(values):
            if v not in self.value_to_keys:
                self.value_to_keys[v] = []
            self.value_to_keys[v].append(i)

    def encrypt(self, word1: str) -> str:
        result = []
        for c in word1:
            if c not in self.key_map:
                return ""
            result.append(self.values[self.key_map[c]])
        return "".join(result)

    def decrypt(self, word2: str) -> int:
        if len(word2) % 2 != 0:
            return 0

        n = len(word2) // 2
        decrypted_strings = set()

        def backtrack(index, current_string):
            if index == n:
                decrypted_strings.add(current_string)
                return

            substring = word2[index * 2 : (index + 1) * 2]
            if substring not in self.value_to_keys:
                return

            for key_index in self.value_to_keys[substring]:
                decrypted_string = current_string + self.keys[key_index]
                backtrack(index + 1, decrypted_string)

        backtrack(0, "")
        return len([s for s in decrypted_strings if s in self.dictionary])
