def solve(source, target):
    def rotate_90(matrix):
        n = len(matrix)
        return [''.join(row[::-1] for row in zip(*matrix))]

    def rotate_180(matrix):
        n = len(matrix)
        return [row[::-1] for row in matrix[::-1]]

    def rotate_270(matrix):
        n = len(matrix)
        return [''.join(row[::-1] for row in zip(*matrix[::-1]))]

    def reflect(matrix):
        n = len(matrix)
        return [''.join(row[::-1]) for row in matrix]

    def is_match(matrix1, matrix2):
        return matrix1 == matrix2

    def transform(matrix, method):
        if method == 1:
            return rotate_90(matrix)
        elif method == 2:
            return rotate_180(matrix)
        elif method == 3:
            return rotate_270(matrix)
        elif method == 4:
            return reflect(matrix)
        elif method == 5:
            return rotate_90(reflect(matrix))
        elif method == 6:
            return matrix
        else:
            return None

    for method in range(1, 8):
        if method == 7:
            break
        transformed = transform(source, method)
        if is_match(transformed, target):
            return method
    return 7
