def solve(list_lengths):
    from functools import lru_cache

    total = sum(list_lengths)
    n = len(list_lengths)

    if total == 0:
        return 0

    # Try all possible initial lengths from 1 to 50
    for initial_length in range(1, 51):
        # Check if total is divisible by initial_length
        if total % initial_length != 0:
            continue

        target = total // initial_length
        if target == 1:
            return initial_length

        # Sort lengths for consistent processing
        list_lengths.sort(reverse=True)

        # Use DFS with memoization to check if we can form 'target' sticks
        # State: (index, current_stick_length, count_of_sticks_formed)
        # We need to form 'target' sticks of length 'initial_length'

        @lru_cache(maxsize=None)
        def dfs(idx, current, count):
            # If all sticks are formed
            if count == target:
                return True

            # If current stick is complete
            if current == initial_length:
                return dfs(0, 0, count + 1)

            # Try to add sticks to current stick
            for i in range(idx, n):
                if list_lengths[i] > initial_length - current:
                    continue
                if list_lengths[i] == 0:
                    continue

                # Skip duplicate lengths to avoid redundant checks
                if i > idx and list_lengths[i] == list_lengths[i-1]:
                    continue

                # Optimization: if we can't form a stick starting from this index, skip
                if current == 0 and dfs(i + 1, 0, count):
                    return True

                if dfs(i + 1, current + list_lengths[i], count):
                    return True

            return False

        if dfs(0, 0, 0):
            return initial_length

    return -1
