def is_black_dead(a):
    rows = len(a)
    if rows == 0:
        return False
    cols = len(a[0])
    if cols == 0:
        return False

    def get_color(r, c):
        if 0 <= r < rows and 0 <= c < cols:
            return a[r][c]
        return 0

    def get_group_color(r, c):
        color = a[r][c]
        if color == 0:
            return 0
        visited = set()
        stack = [(r, c)]
        while stack:
            curr_r, curr_c = stack.pop()
            if (curr_r, curr_c) in visited:
                continue
            visited.add((curr_r, curr_c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighbor_color = a[nr][nc]
                    if neighbor_color == color:
                        stack.append((nr, nc))
        return color

    def count_liberties(r, c):
        color = a[r][c]
        if color == 0:
            return 0
        visited = set()
        stack = [(r, c)]
        liberties = set()
        while stack:
            curr_r, curr_c = stack.pop()
            if (curr_r, curr_c) in visited:
                continue
            visited.add((curr_r, curr_c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    neighbor_color = a[nr][nc]
                    if neighbor_color == 0:
                        liberties.add((nr, nc))
                    elif neighbor_color == color:
                        stack.append((nr, nc))
        return len(liberties)

    for r in range(rows):
        for c in range(cols):
            if a[r][c] == 2:
                if count_liberties(r, c) == 0:
                    return True
    return False
