    def applySubstitutions(self, replacements: List[List[str]], text: str) -> str:
        mapping = {key: value for key, value in replacements}
        def replace(text):
            if not text:
                return text
            i = 0
            result = []
            while i < len(text):
                if text[i:i+2] == '%':
                    if i + 2 < len(text) and text[i+2] == '%':
                        result.append(text[i:i+3])
                        i += 3
                    else:
                        key = text[i+1]
                        if key in mapping:
                            result.append(replace(mapping[key]))
                            i += 2
                        else:
                            result.append(text[i])
                            i += 1
                else:
                    result.append(text[i])
                    i += 1
            return ''.join(result)
        return replace(text)
