class Solution:
    def constructGridLayout(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        adj = collections.defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        degree = collections.defaultdict(int)
        for u, v in edges:
            degree[u] += 1
            degree[v] += 1

        rows = 0
        cols = 0
        for d in degree.values():
            if d % 2 == 1:
                return []
            if d > 0:
                if d % 2 == 0:
                    rows = max(rows, d // 2)
                    cols = max(cols, d // 2)
                else:
                    rows = max(rows, d // 2 + 1)
                    cols = max(cols, d // 2 + 1)

        grid = [[-1] * cols for _ in range(rows)]
        visited = [False] * n

        def dfs(u, r, c):
            visited[u] = True
            grid[r][c] = u
            for v in adj[u]:
                if not visited[v]:
                    if c + 1 < cols and grid[r][c + 1] == -1:
                        dfs(v, r, c + 1)
                    elif r + 1 < rows and grid[r + 1][c] == -1:
                        dfs(v, r + 1, c)
                    elif c - 1 >= 0 and grid[r][c - 1] == -1:
                        dfs(v, r, c - 1)
                    elif r - 1 >= 0 and grid[r - 1][c] == -1:
                        dfs(v, r - 1, c)

        for i in range(n):
            if not visited[i]:
                dfs(i, 0, 0)

        return grid
