class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def is_almost_equal(x: int, y: int) -> bool:
            def get_digits(n: int) -> list:
                if n == 0:
                    return [0]
                digits = []
                while n > 0:
                    digits.append(n % 10)
                    n //= 10
                return digits[::-1]

            def can_make_equal(x: int, y: int) -> bool:
                digits_x = get_digits(x)
                digits_y = get_digits(y)

                # Try swapping any two digits in x to see if it matches y
                for i in range(len(digits_x)):
                    for j in range(i + 1, len(digits_x)):
                        # Swap digits at positions i and j in x
                        new_digits_x = digits_x[:i] + digits_x[j] + digits_x[i+1:]
                        if new_digits_x == digits_y:
                            return True
                return False

            # Try swapping any two digits in y to see if it matches x
            for i in range(len(digits_y)):
                for j in range(i + 1, len(digits_y)):
                    # Swap digits at positions i and j in y
                    new_digits_y = digits_y[:i] + digits_y[j] + digits_y[i+1:]
                    if new_digits_y == digits_x:
                        return True
                return False

            return can_make_equal(x, y) or can_make_equal(y, x)

        count = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if is_almost_equal(nums[i], nums[j]):
                    count += 1
        return count
