    def maxWeight(self, pizzas: List[int]) -> int:
        n = len(pizzas)
        pizzas.sort()
        dp = [[-1] * (n // 2) for _ in range(n // 2)]
        memo = {}

        def solve(idx, day):
            if idx == n // 2:
                return 0
            if (idx, day) in memo:
                return memo[(idx, day)]

            max_gain = 0
