class Solution:
    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        obstacles = []
        results = []

        for x, y in queries:
            dist = abs(x) + abs(y)
            if len(obstacles) < k:
                obstacles.append(dist)
            else:
                obstacles.sort()
                results.append(obstacles[k-1])

            if len(obstacles) < k:
                results.append(-1)
            else:
                heapq.heappush(obstacles, dist)

