class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        def build_graph(pairs, rates):
            graph = collections.defaultdict(dict)
            for (start, target), rate in zip(pairs, rates):
                graph[start][target] = rate
                graph[target][start] = 1.0 / rate
            return graph

        graph1 = build_graph(pairs1, rates1)
        graph2 = build_graph(pairs2, rates2)

        def get_max_currency(currency, graph):
            if currency not in graph:
                return {currency: 1.0}

            max_amounts = {currency: 1.0}
            queue = [currency]
            visited = {currency}

            while queue:
                current = queue.pop(0)
                for neighbor, rate in graph[current].items():
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
                        max_amounts[neighbor] = max_amounts.get(neighbor, 1.0) * rate
                    else:
                        new_amount = max_amounts[current] * rate
                        if new_amount > max_amounts[neighbor]:
                            max_amounts[neighbor] = new_amount
                            queue.append(neighbor)
            return max_amounts

        amounts_after_day1 = get_max_currency(initialCurrency, graph1)

        max_final_amounts = {}
        for currency, amount in amounts_after_day1.items():
            amounts_after_day2 = get_max_currency(currency, graph2)
            for final_currency, final_amount in amounts_after_day2.items():
                if final_currency == initialCurrency:
                    total_amount = amount * final_amount
                    if total_amount not in max_final_amounts or total_amount > max_final_amounts[total_amount]:
                        max_final_amounts[total_amount] = total_amount

        return max(max_final_amounts.values()) if max_final_amounts else 1.0
