class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        total_sum = sum(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        def get_sum(i, j):
            return prefix_sum[j] - prefix_sum[i]

        def remove_first_two():
            return get_sum(0, 1)

        def remove_last_two():
            return get_sum(n - 2, n - 1)

        def remove_first_last():
            return get_sum(0, 0) + get_sum(n - 1, n - 1)

        def remove_first_two_recursive():
            return remove_first_two() + self.maxScore(nums[2:])

        def remove_last_two_recursive():
            return remove_last_two() + self.maxScore(nums[:-2])

        def remove_first_last_recursive():
            return remove_first_last() + self.maxScore(nums[1:-1])

        def solve(i, j):
            if j - i < 2:
                return 0

            op1 = remove_first_two_recursive()
            op2 = remove_last_two_recursive()
            op3 = remove_first_last_recursive()

            return max(op1, op2, op3)

        return solve(0, n - 1)
