            for i in range(n):
                if x1 <= xCoord[i] <= x2 and y1 <= yCoord[i] <= y2:
                    if xCoord[i] == x1 and yCoord[i] == y1:
                        continue
                    if xCoord[i] == x1 and yCoord[i] == y2:
                        continue
                    if xCoord[i] == x2 and yCoord[i] == y1:
                        continue
                    if xCoord[i] == x2 and yCoord[i] == y2:
                        continue
                    if xCoord[i] == x1 or xCoord[i] == x2 or yCoord[i] == y1 or yCoord[i] == y2:
                        return False
            return True

        def is_valid(x1, y1, x2, y2):
            return is_empty(x1, y1, x2, y2)

        max_area = -1

        for i in range(n):
            for j in range(i + 1, n):
                if xCoord[i] == xCoord[j]:
                    continue
                x1, y1 = xCoord[i], yCoord[i]
                x2, y2 = xCoord[j], yCoord[j]

                if x1 > x2:
                    x1, x2 = x2, x1
                    y1, y2 = y2, y1

                if y1 > y2:
                    y1, y2 = y2, y1

                if is_valid(x1, y1, x2, y2):
                    area = (x2 - x1) * (y2 - y1)
                    if area > max_area:
                        max_area = area

        return max_area
