inf = float('inf')

class Solution:
    def minConnectedGroups(self, intervals: List[List[int]], k: int) -> int:
        intervals.sort()
        merged = []
        for start, end in intervals:
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            else:
                merged[-1][1] = max(merged[-1][1], end)

        def count_groups(arr):
            if not arr:
                return 0
            count = 1
            for i in range(1, len(arr)):
                if arr[i][0] > arr[i-1][1]:
                    count += 1
            return count

        def merge_intervals(arr, new_start, new_end):
            new_arr = []
            for start, end in arr:
                if start > new_end:
                    new_arr.append([start, end])
                else:
                    new_arr.append([min(start, new_start), max(end, new_end)])
            return new_arr

        def count_groups_optimized(arr):
            if not arr:
                return 0
            count = 1
            for i in range(1, len(arr)):
                if arr[i][0] > arr[i-1][1]:
                    count += 1
            return count

        original_groups = count_groups(merged)

        best_groups = original_groups

        for i in range(len(merged)):
            for j in range(i + 1, len(merged)):
                if merged[j][0] > merged[i][1] + k:
                    break
                new_start = merged[i][1]
                new_end = merged[j][0]
                if new_end - new_start > k:
                    new_end = new_start + k
                new_merged = merge_intervals(merged, new_start, new_end)
                groups = count_groups_optimized(new_merged)
                best_groups = min(best_groups, groups)

        return best_groups
