        def get_greatest_proper_divisor(n):
            if n == 1:
                return -1
            if n == 2:
                return 1
            if n % 2 == 0:
                return n // 2
            for i in range(3, int(math.sqrt(n)) + 1, 2):
                if n % i == 0:
                    return n // i
            return 1

        def min_ops_to_reach_target(n, target):
            if n <= target:
                return 0
            if target == 1:
                return -1

            ops = 0
            while n > target:
                d = get_greatest_proper_divisor(n)
                if d == -1:
                    return -1
                n = n // d
                ops += 1
                if n <= target:
                    break
            return ops

        ops = 0
        for i in range(len(nums)):
            if i > 0 and nums[i] < nums[i-1]:
                needed = min_ops_to_reach_target(nums[i], nums[i-1])
                if needed == -1:
                    return -1
                ops += needed
                nums[i] = nums[i-1]

        return ops
